<div class="module-toolbar"><a class="btn-primary" href="<?= e(url('turma/criar')) ?>">+ Nova turma</a><a class="btn-secondary" href="<?= e(url('aluno')) ?>">Voltar aos alunos</a></div>
<section class="relatorio"><form class="student-filters" method="get" action="<?= e(url('turma')) ?>"><div><label for="q">Nome</label><input id="q" name="q" value="<?= e($search) ?>" maxlength="100"></div><div><label for="ativo">Situação</label><select id="ativo" name="ativo"><option value="">Todas</option><option value="1" <?= $activeFilter === '1' ? 'selected' : '' ?>>Ativas</option><option value="0" <?= $activeFilter === '0' ? 'selected' : '' ?>>Inativas</option></select></div><div class="filter-actions"><button class="btn-primary" type="submit">Filtrar</button><a class="btn-secondary" href="<?= e(url('turma')) ?>">Limpar</a></div></form></section>
<section class="relatorio"><div class="table-scroll"><table class="tabela-filtrada"><thead><tr><th>Turma</th><th>Ano letivo</th><th>Situação</th><th>Alunos ativos</th><th>Ações</th></tr></thead><tbody>
<?php if ($items === []): ?><tr><td colspan="5" class="empty-state">Nenhuma turma encontrada.</td></tr><?php endif; ?>
<?php foreach ($items as $item): ?><tr><td><?= e((string) $item['nome_turma']) ?></td><td><?= e($item['ano_letivo'] ? (string) $item['ano_letivo'] : 'Legado — preencher') ?></td><td><span class="badge-status <?= (int) $item['ativo'] === 1 ? 'badge-ativo' : 'badge-inativo' ?>"><?= (int) $item['ativo'] === 1 ? 'Ativa' : 'Inativa' ?></span></td><td><?= e((string) $item['alunos_ativos']) ?></td><td class="table-actions"><a class="btn-acao" href="<?= e(url('turma/editar/' . (int) $item['id'])) ?>">Editar</a><form class="inline-form" method="post" action="<?= e(url('turma/status/' . (int) $item['id'])) ?>" data-confirm-status="<?= (int) $item['ativo'] === 1 ? 'Inativar esta turma?' : 'Reativar esta turma?' ?>"><input type="hidden" name="_csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="ativo" value="<?= (int) $item['ativo'] === 1 ? '0' : '1' ?>"><button class="btn-acao" type="submit"><?= (int) $item['ativo'] === 1 ? 'Inativar' : 'Reativar' ?></button></form></td></tr><?php endforeach; ?>
</tbody></table></div></section>
